 val scope=rememberCoroutineScope();var revision by remember{mutableIntStateOf(0)};var stage by remember{mutableIntStateOf(0)};var busy by remember{mutableStateOf(true)};var writing by remember{mutableStateOf(false)};var status by remember{mutableStateOf("正在分析音訊指紋…")}
