  @Composable fun Artwork(mod:Modifier){Column(panel(mod).verticalScroll(rememberScrollState())){Text("專輯封面",fontSize=18.sp);listOf("目前封面" to original.cover,"建議封面" to result?.cover?.bytes).forEach{(label,bytes)->Text(label);AsyncImage(bytes,label,Modifier.fillMaxWidth().height(145.dp));if(bytes==null)Text("沒有可用封面",fontSize=12.sp)else{val bounds=android.graphics.BitmapFactory.Options().apply{inJustDecodeBounds=true};android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.size,bounds);Text("${bounds.outWidth} × ${bounds.outHeight} · ${bounds.outMimeType}",fontSize=11.sp)}};Row(verticalAlignment=Alignment.CenterVertically){RadioButton(!useArt,{useArt=false},enabled=!writing);Text("保留目前封面")};Row(verticalAlignment=Alignment.CenterVertically){RadioButton(useArt,{useArt=true},enabled=result?.cover!=null&&!writing&&!busy);Text("使用建議封面")}}}
